import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_BUS_NUMBER = 1
ADC_GAIN = 1  # Set the gain for the ADC (adjust for your voltage range)
READ_DELAY = 0.5  # Delay between readings in seconds

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus):
    """Initializes the ADC."""
    try:
        return ADS.ADS1115(i2c_bus)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def initialize_channels(adc_instance):
    """Initializes the ADC channels."""
    try:
        return [AnalogIn(adc_instance, ADS.P0),
                AnalogIn(adc_instance, ADS.P1),
                AnalogIn(adc_instance, ADS.P2),
                AnalogIn(adc_instance, ADS.P3)]
    except Exception as e:
        print(f"Error initializing channels: {e}")
        return None

def read_adc_values(channels):
    """Reads the ADC values from all channels."""
    if channels is None:
        return None
    try:
        return [channel.value for channel in channels]
    except Exception as e:
        print(f"Error reading ADC values: {e}")
        return None

def print_header():
    """Prints the header for the ADC table."""
    print('| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*['Channel {}'.format(i) for i in range(4)]))
    print('-' * 37)

def print_adc_values(values):
    """Prints the ADC values in a formatted table row."""
    if values is None:
        return
    print('| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*values))

def main():
    """Main function to read and display ADC values."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    adc = initialize_adc(i2c_bus)
    if adc is None:
        return

    channels = initialize_channels(adc)
    if channels is None:
        return

    try:
        while True:
            adc_values = read_adc_values(channels)
            if adc_values:
                print_header()
                print_adc_values(adc_values)
            time.sleep(READ_DELAY)

    except KeyboardInterrupt:
        print("\nExiting program.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        # No specific cleanup needed for I2C or ADC in this library,
        # but good practice to include a finally block for potential future changes.
        print("Program finished.")

if __name__ == "__main__":
    main()

