import cv2
import imutils
import time
from imutils.video import VideoStream

# Define constants
CASCADE_PATH = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
RESIZE_WIDTH = 450
SCALE_FACTOR = 1.1
MIN_NEIGHBORS = 5
MIN_FACE_SIZE = (30, 30)
DISPLAY_WINDOW_NAME = "Frame"
QUIT_KEY = "q"
CAMERA_WARMUP_TIME = 2.0
FRAME_PROCESSING_INTERVAL = 0.1  # seconds

def initialize_camera():
    """Initializes the video stream from the Raspberry Pi camera."""
    try:
        video_stream = VideoStream(usePiCamera=True).start()
        time.sleep(CAMERA_WARMUP_TIME)
        return video_stream
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def load_face_cascade(cascade_path):
    """Loads the Haar cascade classifier for face detection."""
    try:
        face_cascade = cv2.CascadeClassifier(cascade_path)
        if face_cascade.empty():
            raise IOError(f"Unable to load face cascade file: {cascade_path}")
        return face_cascade
    except Exception as e:
        print(f"Error loading face cascade: {e}")
        return None

def process_frame(frame, face_cascade):
    """Resizes, converts to grayscale, and detects faces in a frame."""
    try:
        resized_frame = imutils.resize(frame, width=RESIZE_WIDTH)
        gray_frame = cv2.cvtColor(resized_frame, cv2.COLOR_BGR2GRAY)
        faces = face_cascade.detectMultiScale(
            gray_frame,
            scaleFactor=SCALE_FACTOR,
            minNeighbors=MIN_NEIGHBORS,
            minSize=MIN_FACE_SIZE,
            flags=cv2.CASCADE_SCALE_IMAGE,
        )
        return resized_frame, faces
    except Exception as e:
        print(f"Error processing frame: {e}")
        return None, []

def draw_rectangles(frame, faces):
    """Draws rectangles around detected faces in the frame."""
    try:
        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
    except Exception as e:
        print(f"Error drawing rectangles: {e}")

def display_frame(frame, window_name):
    """Displays the frame in a window."""
    try:
        cv2.imshow(window_name, frame)
    except Exception as e:
        print(f"Error displaying frame: {e}")

def main():
    """Main function to run the face detection."""
    video_stream = initialize_camera()
    if video_stream is None:
        return

    face_cascade = load_face_cascade(CASCADE_PATH)
    if face_cascade is None:
        video_stream.stop()
        return

    try:
        while True:
            frame = video_stream.read()
            if frame is None:
                print("Error reading frame from camera.")
                break

            processed_frame, faces = process_frame(frame, face_cascade)
            if processed_frame is None:
                break

            draw_rectangles(processed_frame, faces)
            display_frame(processed_frame, DISPLAY_WINDOW_NAME)

            key = cv2.waitKey(int(FRAME_PROCESSING_INTERVAL * 1000)) & 0xFF
            if key == ord(QUIT_KEY):
                break

    except KeyboardInterrupt:
        print("Program interrupted by user.")

    finally:
        cv2.destroyAllWindows()
        video_stream.stop()
        print("Camera and display resources released.")

if __name__ == "__main__":
    main()

