import logging
import sys
import time
import cv2
import numpy as np
import RPi.GPIO as GPIO
from servo import Servo
from uart import UART

# Configure logging
logging.basicConfig(stream=sys.stdout, level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
CAMERA_WIDTH = 320
CAMERA_HEIGHT = 240
CAMERA_FPS = 16
CENTER_X = CAMERA_WIDTH // 2
CENTER_Y = CAMERA_HEIGHT // 2
TARGET_MIN_AREA = 10
SERVO_PIN_AZIMUTH = 7
SERVO_PIN_ELEVATION = 13
SERVO_FREQUENCY = 50
SERVO_INITIAL_DUTY_CYCLE = 7.0
SERVO_INCREMENT = 0.1
SERVO_MAX_DUTY_CYCLE = 12.0
UART_PORT = "/dev/ttyACM0"
UART_BAUDRATE = 115200
API_CALL_INTERVAL = 0.8  # seconds
MIN_DISTANCE = 10
MAX_DISTANCE = 30
YELLOW_THRESHOLD = 25

class ObjectTracker:
    """Tracks a red object using a CSI camera and controls servos via UART."""

    def __init__(self):
        """Initializes the ObjectTracker."""
        self.camera = None
        self.uart = None
        self.azimuth_servo = None
        self.elevation_servo = None
        self.search_duty_cycle = SERVO_INITIAL_DUTY_CYCLE
        self.is_searching = False
        self.api_call_timer = 0

    def initialize_components(self):
        """Initializes camera, UART, and servos."""
        try:
            self.camera = self._initialize_camera()
            self.uart = self._initialize_uart()
            self.azimuth_servo = self._initialize_servo(SERVO_PIN_AZIMUTH)
            self.elevation_servo = self._initialize_servo(SERVO_PIN_ELEVATION)
            self.elevation_servo.set_angle(0)  # Start at lowest elevation
            time.sleep(1)  # Allow servos to initialize
        except Exception as e:
            logger.error(f"Initialization failed: {e}")
            self.cleanup()
            sys.exit(1)

    def _initialize_camera(self):
        """Initializes the CSI camera."""
        try:
            camera = cv2.VideoCapture(0, cv2.CAP_V4L2)
            camera.set(cv2.CAP_PROP_FRAME_WIDTH, CAMERA_WIDTH)
            camera.set(cv2.CAP_PROP_FRAME_HEIGHT, CAMERA_HEIGHT)
            camera.set(cv2.CAP_PROP_FPS, CAMERA_FPS)
            if not camera.isOpened():
                raise IOError("Cannot open camera")
            return camera
        except Exception as e:
            logger.error(f"Camera initialization failed: {e}")
            raise

    def _initialize_uart(self):
        """Initializes the UART communication."""
        try:
            uart = UART(UART_PORT, UART_BAUDRATE)
            return uart
        except Exception as e:
            logger.error(f"UART initialization failed: {e}")
            raise

    def _initialize_servo(self, pin):
        """Initializes a servo motor."""
        try:
            servo = Servo(pin, SERVO_FREQUENCY, SERVO_INITIAL_DUTY_CYCLE)
            return servo
        except Exception as e:
            logger.error(f"Servo initialization failed on pin {pin}: {e}")
            raise

    def run(self):
        """Main loop for object tracking."""
        try:
            self.initialize_components()
            while True:
                self.process_frame()
        except KeyboardInterrupt:
            logger.info("Exiting program.")
        except Exception as e:
            logger.error(f"An unexpected error occurred: {e}")
        finally:
            self.cleanup()

    def process_frame(self):
        """Captures a frame, processes it, and controls servos and UART."""
        try:
            ret, frame = self.camera.read()
            if not ret:
                logger.warning("Failed to capture frame.")
                return

            frame = self._process_image(frame)
            self._control_servos(frame)

        except Exception as e:
            logger.error(f"Frame processing failed: {e}")

    def _process_image(self, frame):
        """Processes the image to detect and highlight the red object."""
        hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
        mask_1 = cv2.inRange(hsv_frame, np.array([160, 160, 10]), np.array([190, 255, 255]))
        ycr_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
        mask_2 = cv2.inRange(ycr_frame, np.array((0., 165., 0.)), np.array((255., 255., 255.)))
        mask = mask_1 | mask_2

        contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        for contour in contours:
            area = cv2.contourArea(contour)
            if area > TARGET_MIN_AREA:
                x, y, w, h = cv2.boundingRect(contour)
                cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
                self._send_object_coordinates(x, y, w, h)

        cv2.imshow("Mask", mask)
        cv2.imshow("Frame", frame)

        return frame

    def _send_object_coordinates(self, x, y, w, h):
        """Sends object coordinates to the UART via API calls."""
        center_x = x + w // 2
        center_y = y + h // 2

        if time.time() - self.api_call_timer < API_CALL_INTERVAL:
            return

        try:
            if MIN_DISTANCE < self.get_distance(center_x, center_y) < MAX_DISTANCE:
                if 100 < center_x < 220:
                    self.uart.send("a")  # Move left
                elif 220 <= center_x <= 320:
                    self.uart.send("b")  # Move very left
                elif 40 <= center_x < 160:
                    self.uart.send("g")  # Move right
                elif 160 <= center_x <= 260:
                    self.uart.send("j")  # Move very right
                else:
                    self.uart.send("k")  # Stop moving horizontally

                if 120 < center_y < 180:
                    self.uart.send("c")  # Move forward
                elif 180 <= center_y <= 240:
                    self.uart.send("d")  # Move very forward
                elif 60 <= center_y < 120:
                    self.uart.send("f")  # Move backward
                else:
                    self.uart.send("h")  # Stop moving vertically

            else:
                self.uart.send("h")  # Stop moving

            self.api_call_timer = time.time()

        except Exception as e:
            logger.error(f"UART communication failed: {e}")

    def get_distance(self, x, y):
        """Calculates the distance between the object and the center of the frame."""
        distance = np.sqrt((x - CENTER_X)**2 + (y - CENTER_Y)**2)
        return distance

    def _control_servos(self, frame):
        """Controls the servos based on the presence of the red object."""
        try:
            height, _, _ = frame.shape
            center_y = height // 2

            if np.sum(frame) == 0:  # Check if the frame is empty (no red object)
                if not self.is_searching:
                    logger.info("Starting search mode.")
                    self.is_searching = True
                    self.elevation_servo.set_angle(0)  # Reset elevation

                self.search_duty_cycle += SERVO_INCREMENT
                if self.search_duty_cycle > SERVO_MAX_DUTY_CYCLE:
                    self.search_duty_cycle = SERVO_INITIAL_DUTY_CYCLE
                    self.elevation_servo.increment_angle(10)  # Increment elevation

                self.azimuth_servo.set_duty_cycle(self.search_duty_cycle)
            else:
                if self.is_searching:
                    logger.info("Object detected. Exiting search mode.")
                    self.is_searching = False

                # Adjust azimuth based on object position (simplified)
                if center_x < CENTER_X - 20:
                    self.azimuth_servo.increment_duty_cycle(-0.5)
                elif center_x > CENTER_X + 20:
                    self.azimuth_servo.increment_duty_cycle(0.5)

                # Adjust elevation based on object position (simplified)
                if center_y < CENTER_Y - 20:
                    self.elevation_servo.increment_angle(-1)
                elif center_y > CENTER_Y + 20:
                    self.elevation_servo.increment_angle(1)

        except Exception as e:
            logger.error(f"Servo control failed: {e}")

    def cleanup(self):
        """Releases resources."""
        try:
            if self.camera:
                self.camera.release()
            if self.uart:
                self.uart.close()
            if self.azimuth_servo:
                self.azimuth_servo.cleanup()
            if self.elevation_servo:
                self.elevation_servo.cleanup()
            cv2.destroyAllWindows()
            GPIO.cleanup()
        except Exception as e:
            logger.error(f"Cleanup failed: {e}")


if __name__ == "__main__":
    tracker = ObjectTracker()
    tracker.run()

