import serial
import time
import sys

# Define the serial port configuration
BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400
BLUETOOTH_TIMEOUT = 1

def configure_bluetooth_serial(port, baudrate, timeout):
    """Configures and returns a serial port object."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error configuring serial port: {e}")
        sys.exit(1)

def send_data_to_bluetooth(serial_port, data):
    """Sends data to the Bluetooth module."""
    try:
        serial_port.write(b'X' + data.encode('utf-8'))
        print(f"Sent: {data}")
    except serial.SerialException as e:
        print(f"Error sending data: {e}")

def main():
    """Main function to handle user input and send data."""
    bluetooth_serial = configure_bluetooth_serial(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE, BLUETOOTH_TIMEOUT)

    try:
        while True:
            user_input = input("Enter data to send (or 'q' to quit): ")
            if user_input.lower() == 'q':
                break
            send_data_to_bluetooth(bluetooth_serial, user_input)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if bluetooth_serial.is_open:
            bluetooth_serial.close()
            print("Bluetooth port closed.")

if __name__ == "__main__":
    main()

