import cv2
import pyzbar.pyzbar as pyzbar
import datetime
import csv
import os

# Configuration
CAMERA_INDEX = 0
INVENTORY_LOG_FILE = "inventory_log.csv"
ERROR_LOG_FILE = "error_log.txt"
CAMERA_IDENTIFIER = "Camera 1"

def initialize_camera():
    """Initializes the USB camera."""
    try:
        cap = cv2.VideoCapture(CAMERA_INDEX)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")
        return cap
    except IOError as e:
        log_error(f"Camera initialization failed: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes from a frame."""
    try:
        decoded_objects = pyzbar.decode(frame)
        if decoded_objects:
            return decoded_objects[0].data.decode("utf-8")
        return None
    except Exception as e:
        log_error(f"QR code decoding failed: {e}")
        return None

def validate_item_identifier(item_identifier):
    """Validates the item identifier."""
    if not item_identifier:
        return False
    return all(c.isalnum() for c in item_identifier)

def log_inventory_event(item_identifier):
    """Logs the inventory event to a CSV file."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        file_exists = os.path.isfile(INVENTORY_LOG_FILE)
        with open(INVENTORY_LOG_FILE, "a", newline="") as csvfile:
            fieldnames = ["Camera", "Item Identifier", "Timestamp"]
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            if not file_exists:
                writer.writeheader()
            writer.writerow({"Camera": CAMERA_IDENTIFIER, "Item Identifier": item_identifier, "Timestamp": timestamp})
    except Exception as e:
        log_error(f"Inventory logging failed: {e}")

def log_error(error_message):
    """Logs an error message to the error log file."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {error_message}\n")
    except Exception as e:
        print(f"FATAL: Could not write to error log: {e}")

def main():
    """Main function to run the QR code inventory system."""
    camera = initialize_camera()
    if camera is None:
        print("Failed to initialize camera. Exiting.")
        return

    try:
        while True:
            ret, frame = camera.read()
            if not ret:
                log_error("Failed to capture frame")
                break

            gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            item_identifier = decode_qr_code(gray_frame)

            if item_identifier and validate_item_identifier(item_identifier):
                log_inventory_event(item_identifier)
                print(f"Item scanned: {item_identifier}")

            cv2.imshow("QR Code Scanner", gray_frame)
            if cv2.waitKey(20) & 0xFF == ord('q'):
                break

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        camera.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

