# Monitors temperature from an RS485 sensor on a Raspberry Pi.

import serial
import time

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
TIMEOUT = 1
READ_INTERVAL = 0.5

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature(serial_port):
    """Reads temperature data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature = float(line)
            return temperature
        return None
    except ValueError:
        print("Invalid data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None

def display_temperature(temperature):
    """Displays the temperature."""
    if temperature is not None:
        print(f"Temperature: {temperature:.1f} C")

def main():
    """Main function to monitor temperature."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            temperature = read_temperature(serial_connection)
            display_temperature(temperature)
            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

