# Environmental Monitoring Script for Raspberry Pi 5
# Reads temperature, humidity, and light from BME280 and TSL2591 sensors
# via a TCA9548A I2C multiplexer.

import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except ValueError as e:
    print(f"Error initializing I2C bus: {e}")
    exit(1)

# Initialize TCA9548A multiplexer
try:
    i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
except ValueError as e:
    print(f"Error initializing TCA9548A multiplexer: {e}")
    exit(1)

# Initialize BME280 sensor
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_multiplexer[0])
except ValueError as e:
    print(f"Error initializing BME280 sensor: {e}")
    bme280_sensor = None  # Set to None to avoid further errors

# Initialize TSL2591 sensor
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer[1])
except ValueError as e:
    print(f"Error initializing TSL2591 sensor: {e}")
    tsl2591_sensor = None  # Set to None to avoid further errors

# Main loop for reading and displaying sensor data
try:
    while True:
        # Read BME280 data
        if bme280_sensor:
            try:
                temperature = bme280_sensor.temperature
                humidity = bme280_sensor.humidity
                print(f"BME280: Temperature = {temperature:.2f} C, Humidity = {humidity:.2f} %")
            except RuntimeError as e:
                print(f"Error reading BME280 sensor: {e}")

        # Read TSL2591 data
        if tsl2591_sensor:
            try:
                light = tsl2591_sensor.lux
                print(f"TSL2591: Light = {light:.2f} lux")
            except RuntimeError as e:
                print(f"Error reading TSL2591 sensor: {e}")

        # Wait before next reading
        time.sleep(2)

except KeyboardInterrupt:
    print("Exiting program.")
except Exception as e:
    print(f"An unexpected error occurred: {e}")

