# Logs temperature data from a UART sensor to a CSV file on Raspberry Pi.

import serial
import time
import csv
import sys

# Configuration
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1
LOG_FILE = 'temperature_log.csv'

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

def read_temperature(serial_port):
    """Reads temperature data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print(f"Error: Invalid data received: {line}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None

def log_temperature(log_file, timestamp, celsius, fahrenheit):
    """Logs the temperature data to a CSV file."""
    try:
        file_exists = False
        try:
            with open(log_file, 'r') as f:
                file_exists = True
        except FileNotFoundError:
            pass

        with open(log_file, 'a', newline='') as csvfile:
            fieldnames = ['Timestamp', 'Temperature_C', 'Temperature_F']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

            if not file_exists:
                writer.writeheader()

            writer.writerow({
                'Timestamp': timestamp,
                'Temperature_C': celsius,
                'Temperature_F': fahrenheit
            })
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    """Main function to read and log temperature data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    try:
        while True:
            temperature_celsius = read_temperature(serial_connection)

            if temperature_celsius is not None:
                temperature_fahrenheit = (temperature_celsius * 9/5) + 32
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_temperature(LOG_FILE, timestamp, temperature_celsius, temperature_fahrenheit)
                print(f"Logged: {timestamp}, Celsius: {temperature_celsius:.2f}, Fahrenheit: {temperature_fahrenheit:.2f}")
            time.sleep(1)  # Adjust delay as needed

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        serial_connection.close()
        print("Serial port closed.")

if __name__ == "__main__":
    main()

