def main():
    """Main function to read and log temperature data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    try:
        while True:
            temperature_celsius = read_temperature(serial_connection)

            if temperature_celsius is not None:
                temperature_fahrenheit = (temperature_celsius * 9/5) + 32
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_temperature(LOG_FILE, timestamp, temperature_celsius, temperature_fahrenheit)
                print(f"Logged: {timestamp}, Celsius: {temperature_celsius:.2f}, Fahrenheit: {temperature_fahrenheit:.2f}")
            time.sleep(1)  # Adjust delay as needed

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        serial_connection.close()
        print("Serial port closed.")

if __name__ == "__main__":
