# Reads temperature and humidity from a UART sensor and triggers alerts.

import serial
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# UART configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Alert thresholds
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def initialize_uart(port, baudrate, timeout):
    """Initializes the UART connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        logging.info(f"UART initialized on {port} at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Failed to initialize UART: {e}")
        return None

def read_sensor_data(serial_connection):
    """Reads temperature and humidity data from the sensor."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature, humidity = line.split(',')
            return float(temperature), float(humidity)
        else:
            return None, None
    except ValueError as e:
        logging.error(f"Invalid data format received: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Error reading sensor data: {e}")
        return None, None

def check_alerts(temperature, humidity):
    """Checks if temperature or humidity exceeds thresholds and logs alerts."""
    if temperature is not None and temperature > TEMP_THRESHOLD:
        logging.warning(f"High temperature alert! Temperature: {temperature:.1f}°C")
    if humidity is not None and humidity > HUMIDITY_THRESHOLD:
        logging.warning(f"High humidity alert! Humidity: {humidity:.1f}%")

def main():
    """Main function to read sensor data and trigger alerts."""
    serial_connection = initialize_uart(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        logging.error("Failed to initialize UART. Exiting.")
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(serial_connection)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                check_alerts(temperature, humidity)

            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logging.info("UART connection closed.")

if __name__ == "__main__":
    main()

