# Door sensor reader for Raspberry Pi using event-driven approach
# Reads a magnetic reed switch connected to GPIO22 (BCM numbering)
# Prints "Door Closed" when the door is closed, "Door Open" when open

import RPi.GPIO as GPIO
import time

# Define the GPIO pin connected to the reed switch
REED_SWITCH_PIN = 22

def setup_gpio():
    """Set up the GPIO pin for the reed switch."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(REED_SWITCH_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def read_door_state(pin):
    """Read the current state of the door sensor."""
    return GPIO.input(pin)

def print_door_status(state):
    """Print the door status based on the sensor reading."""
    if state == GPIO.LOW:
        print("Door Closed")
    else:
        print("Door Open")

def main_loop():
    """Main loop to continuously monitor the door sensor."""
    try:
        while True:
            door_state = read_door_state(REED_SWITCH_PIN)
            print_door_status(door_state)
            time.sleep(1)  # Check every second
    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    setup_gpio()
    main_loop()

