import RPi.GPIO as GPIO
import time
import signal
import sys

# Define GPIO pins for the sensors
SENSOR_PINS = [17, 27, 22]

# Global flag to control the main loop
running = True

def signal_handler(sig, frame):
    """Handles Ctrl+C and SIGTERM signals for graceful shutdown."""
    global running
    print("Exiting gracefully...")
    running = False

def initialize_gpio(pins):
    """Initializes GPIO pins as input with pull-up resistors."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in pins:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def read_sensor_data(pins):
    """Reads data from the specified GPIO pins."""
    responses = []
    for pin in pins:
        try:
            if GPIO.input(pin) == GPIO.HIGH:
                responses.append(f"Response for sensor {pins.index(pin) + 1}")
        except Exception as e:
            print(f"Error reading sensor {pins.index(pin) + 1}: {e}")
    return responses

def main():
    """Main function to continuously poll sensors and print responses."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio(SENSOR_PINS)

    print(f"Monitoring sensors on pins: {SENSOR_PINS}")
    print(f"Polling interval: 1 second")

    try:
        while running:
            responses = read_sensor_data(SENSOR_PINS)
            if responses:
                print(" ".join(responses))
            time.sleep(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

