import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for GPIO pin assignments (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Protocol constants
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
BASE_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Timing constants (seconds)
TRANSMIT_DELAY = 0.0005
RECEIVE_TIMEOUT = 1


class GPIOError(Exception):
    """Custom exception for GPIO related errors."""
    pass


def setup_gpio():
    """Initializes GPIO pins and sets their modes."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        GPIO.setup(DATA_OUT_PIN, GPIO.OUT, initial=0)
        GPIO.setup(TIMER_OUT_PIN, GPIO.OUT, initial=0)
        GPIO.setup(DATA_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)  # Enable pull-down resistor
        GPIO.setup(TIMER_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN) # Enable pull-down resistor

        logger.info("GPIO setup complete.")
    except Exception as e:
        raise GPIOError(f"GPIO setup failed: {e}")


def buffer_to_char(buffer):
    """Converts a buffer list to a character."""
    try:
        binary_string = "0b" + "".join(map(str, buffer))
        return chr(int(binary_string, 2))
    except Exception as e:
        raise ValueError(f"Invalid buffer format: {e}")


def char_to_buffer(char):
    """Converts a character to a buffer list."""
    try:
        binary = bin(ord(char))[2:].zfill(7)
        return [0] + [int(bit) for bit in binary]
    except Exception as e:
        raise ValueError(f"Invalid character: {e}")


def string_to_buffer_list(input_string):
    """Converts a string to a list of buffers."""
    return [char_to_buffer(char) for char in input_string]


def buffer_list_to_string(buffer_list):
    """Converts a list of buffers to a string, ignoring start and end signals."""
    return "".join(buffer_to_char(buffer) for buffer in buffer_list if buffer not in (START_SIGNAL, END_SIGNAL))


def transmit_bit(bit):
    """Transmits a single bit."""
    try:
        GPIO.output(TIMER_OUT_PIN, 0)
        GPIO.output(DATA_OUT_PIN, bit)
        time.sleep(TRANSMIT_DELAY)
        GPIO.output(TIMER_OUT_PIN, 1)
        time.sleep(TRANSMIT_DELAY)
        GPIO.output(TIMER_OUT_PIN, 0)
    except Exception as e:
        raise GPIOError(f"Bit transmission failed: {e}")


def transmit_data(data_string):
    """Transmits a string of data."""
    try:
        setup_gpio()
        buffer_list = string_to_buffer_list(data_string) + [END_SIGNAL]

        for buffer in buffer_list:
            for bit in buffer:
                transmit_bit(bit)

        logger.info(f"Transmitted: {data_string}")

    except GPIOError as e:
        logger.error(e)
        raise  # Re-raise the exception to be handled by the caller
    except Exception as e:
        logger.exception(f"Unexpected error during transmission: {e}")
        raise
    finally:
        GPIO.cleanup()


def receive_bit():
    """Receives a single bit."""
    timeout_start = time.time()
    while GPIO.input(TIMER_IN_PIN) == 0:
        if time.time() - timeout_start > RECEIVE_TIMEOUT:
            raise GPIOError("Receive timeout waiting for timer signal.")

    timeout_start = time.time()
    while GPIO.input(TIMER_IN_PIN) == 1:
        if time.time() - timeout_start > RECEIVE_TIMEOUT:
            raise GPIOError("Receive timeout waiting for timer signal to change.")

    return GPIO.input(DATA_IN_PIN)


def receive_data():
    """Receives data and returns it as a string."""
    try:
        setup_gpio()
        received_buffers = []
