DEFAULT_ERROR_PIN = 10  # BCM 15
DEFAULT_PWM_PIN = 12  # BCM 18
DEFAULT_WATCHDOG_TIMEOUT = 20  # seconds

# Global flag for graceful shutdown
shutdown_flag = False

class GPIODevice:
    """
    Manages GPIO pin initialization and cleanup.
    """
    def __init__(self, pin_number, pin_type="OUT", initial_value=GPIO.LOW):
        self.pin_number = pin_number
        self.pin_type = pin_type
        self.initial_value = initial_value
        self.gpio_initialized = False

    def initialize(self):
        """Initializes the GPIO pin."""
        try:
            GPIO.setmode(GPIO.BOARD)  # Use BOARD pin numbering
            if self.pin_type == "OUT":
                GPIO.setup(self.pin_number, GPIO.OUT)
                GPIO.output(self.pin_number, self.initial_value)
            elif self.pin_type == "IN":
                GPIO.setup(self.pin_number, GPIO.IN)
            self.gpio_initialized = True
            logger.info(f"GPIO pin {self.pin_number} initialized successfully.")
        except Exception as e:
            logger.error(f"Failed to initialize GPIO pin {self.pin_number}: {e}")
            raise

    def set_value(self, value):
        """Sets the GPIO pin value."""
        if not self.gpio_initialized:
            logger.warning(f"GPIO pin {self.pin_number} not initialized. Cannot set value.")
            return

        try:
            GPIO.output(self.pin_number, value)
            logger.debug(f"GPIO pin {self.pin_number} set to {value}.")
        except Exception as e:
            logger.error(f"Failed to set GPIO pin {self.pin_number} to {value}: {e}")

    def cleanup(self):
        """Cleans up the GPIO pin."""
        if self.gpio_initialized:
            try:
                GPIO.output(self.pin_number, GPIO.LOW)  # Ensure pin is low before cleanup
                GPIO.cleanup(self.pin_number)
                logger.info(f"GPIO pin {self.pin_number} cleaned up successfully.")
            except Exception as e:
                logger.error(f"Failed to cleanup GPIO pin {self.pin_number}: {e}")
            finally:
                self.gpio_initialized = False


class SubscriptionHandler:
    """
    Handles subscriptions to data streams.
    """
    def __init__(self, subscriber_socket, subscription_callback):
        self.subscriber_socket = subscriber_socket
        self.subscription_callback = subscription_callback
        self.subscriptions = {}

    def handle_command(self, command):
        """Processes commands related to subscriptions."""
        action = command.get('action')
        stream_filter = command.get('stream_filter')

        if not stream_filter:
            logger.error("Stream filter is required for subscription commands.")
            return

        if action == 'SUBSCRIBE':
            if stream_filter not in self.subscriptions:
                self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, stream_filter)
                self.subscriptions[stream_filter] = []
                logger.info(f"Subscribed to stream filter: {stream_filter}")
            self.subscriptions[stream_filter].append(command['callback'])
        elif action == 'UNSUBSCRIBE':
            if stream_filter in self.subscriptions:
                self.subscriber_socket.setsockopt_string(zmq.UNSUBSCRIBE, stream_filter)
                del self.subscriptions[stream_filter]
                logger.info(f"Unsubscribed from stream filter: {stream_filter}")
        elif action == 'REMOVE_ALL_CBS':
            if stream_filter in self.subscriptions:
                del self.subscriptions[stream_filter]
                logger.info(f"Removed all callbacks for stream filter: {stream_filter}")
        elif action == 'RESET':
            self.reset()
            logger.info("Reset all callbacks.")
        else:
            logger.warning(f"Unknown action: {action}")

    def reset(self):
        """Resets all subscription callbacks."""
        for stream_filter in self.subscriptions:
            self.subscriptions[stream_filter] = []
        logger.info("All callbacks reset.")

    def process_subscriptions(self):
        """Processes incoming data and triggers callbacks."""
        try:
            [stream_filter, message] = self.subscriber_socket.recv_multipart()
            logger.debug(f"Received message on stream filter: {stream_filter}")

            if stream_filter in self.subscriptions:
                for callback in self.subscriptions[stream_filter]:
                    try:
                        callback(message)
                    except Exception as e:
                        logger.error(f"Error executing callback for stream filter {stream_filter}: {e}")
        except zmq.ZMQError as e:
            if e.errno == zmq.EAGAIN:
                # No message available, continue looping
                return
            else:
                logger.error(f"ZMQError in process_subscriptions: {e}")
        except Exception as e:
            logger.error(f"Error processing subscriptions: {e}")


class PIDHandler:
    """
    Handles PID control and error output.
    """
    def __init__(self, config, pwm_frequency=DEFAULT_PWM_FREQUENCY, error_pin=DEFAULT_ERROR_PIN, pwm_pin=DEFAULT_PWM_PIN, watchdog_timeout=DEFAULT_WATCHDOG_TIMEOUT):
        self.config = config
        self.pwm_frequency = pwm_frequency
        self.error_pin = error_pin
        self.pwm_pin = pwm_pin
        self.watchdog_timeout = watchdog_timeout
        self.global_err_state = False
        self.last_msg = time.time()
        self.subscriber_socket = None
        self.subscription_handler = None
        self.pwm_device = None
        self.error_device = None

        # Initialize GPIO devices
        try:
            self.error_device = GPIODevice(self.error_pin, pin_type="OUT", initial_value=GPIO.LOW)
            self.error_device.initialize()

            if self.config.get('pwm_err'):
                self.pwm_device = GPIODevice(self.pwm_pin, pin_type="OUT")
                self.pwm_device.initialize()
                self.pwm = GPIO.PWM(self.pwm_pin, self.pwm_frequency)
                self.pwm.start(0.0)
                logger.info("PWM error output enabled.")
            else:
                logger.info("PWM error output disabled.")
        except Exception as e:
            logger.error(f"Failed to initialize GPIO devices: {e}")
            raise

    def connect_subscriber(self, subscriber_socket):
        """Connects the PID handler to a subscriber socket."""
        self.subscriber_socket = subscriber_socket
        self.subscription_handler = SubscriptionHandler(self.subscriber_socket, self.handle_command)

    def handle_command(self, command):
        """Processes incoming commands."""
        try:
            action = command.get('action')
            if action in ('RESET', 'MUTE', 'UNMUTE', 'PAUSE', 'RESTART', 'UPDATE_KW', 'UPDATE_PARMS'):
                self.update_error_output()
            else:
                logger.warning(f"Unknown command action: {action}")
        except Exception as e:
            logger.error(f"Error handling command: {e}")

    def update_error_output(self):
        """Updates the error output based on the current global error state."""
        if self.config.get('pwm_err'):
            if self.global_err_state:
                self.pwm.ChangeDutyCycle(self.config['pwm_dutycycle'])
            else:
                self.pwm.ChangeDutyCycle(0.0)
        else:
            if self.global_err_state:
                self.error_device.set_value(GPIO.HIGH)
            else:
                self.error_device.set_value(GPIO.LOW)

    def set_error_output(self, state):
        """Sets the global error state and updates the output."""
        self.global_err_state = state
        self.update_error_output()

    def watchdog(self):
        """Monitors for watchdog timeouts and triggers error output."""
        if time.time() - self.last_msg > self.watchdog_timeout:
            logger.error("Watchdog timeout! Triggering error output.")
            self.set_error_output(True)
        else:
            self.set_error_output(False)

    def handle_message(self, message):
        """Processes incoming messages and updates the watchdog."""
        try:
            self.last_msg = time.time()
            if self.subscription_handler:
                self.subscription_handler.process_subscriptions()
        except Exception as e:
            logger.error(f"Error handling message: {e}")

    def cleanup(self):
        """Cleans up GPIO resources."""
        logger.info("Cleaning up GPIO resources.")
        if self.pwm_device:
            self.pwm_device.cleanup()
        if self.error_device:
            self.error_device.cleanup()
        GPIO.cleanup()


def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    global shutdown_flag
    logger.info(f"Received signal {sig}. Shutting down...")
    shutdown_flag = True


def main():
    """Main function to initialize and run the PID handler."""
    global shutdown_flag

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize PIDHandler with configuration (replace with your actual config)
    config = {
        'pwm_err': True,
        'pwm_dutycycle': 50.0,
    }
    pid_handler = PIDHandler(config)

    # Connect to the subscriber socket (replace with your actual connection)
    context = zmq.Context()
    subscriber_socket = context.socket(zmq.SUB)
    subscriber_socket.setsockopt(zmq.LINGER, 0)
    subscriber_socket.connect('tcp://127.0.0.1:5557')

    # Connect the PID handler to the subscriber socket
    pid_handler.connect_subscriber(subscriber_socket)

    # Subscribe to any desired streams
    pid_handler.subscription_handler.handle_command({
        'action': 'SUBSCRIBE',
        'stream_filter': 'stream1',
        'callback': lambda msg: logger.info(f"Received message on stream1: {msg}")
    })

    try:
        logger.info("Starting PID handler loop.")
        while not shutdown_flag:
            pid_handler.watchdog()
            pid_handler.handle_message(None)  # Process incoming messages
            time.sleep(0.1)  # Adjust sleep time as needed
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure proper cleanup on exit
        pid_handler.cleanup()
        subscriber_socket.close()
        context.term()
        logger.info("PID handler stopped.")


if __name__ == "__main__":
    main()

