import RPi.GPIO as GPIO
import time
import sys

# Define the GPIO pin connected to the fan
FAN_PIN = 12

# Define the PWM frequency (25kHz is a common value for fans)
PWM_FREQUENCY = 25000

def setup_gpio():
    """Sets up the GPIO pin for PWM control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        return False

def set_fan_speed(pwm_instance, speed_percent):
    """Sets the fan speed using PWM duty cycle."""
    try:
        pwm_instance.ChangeDutyCycle(speed_percent)
        print(f"Fan speed set to {speed_percent}%")
    except Exception as e:
        print(f"Error setting fan speed: {e}")

def main():
    """Main function to control the fan speed."""
    if not setup_gpio():
        sys.exit(1)

    try:
        # Try to use hardware PWM
        pwm_instance = GPIO.PWM(FAN_PIN, PWM_FREQUENCY)
        pwm_instance.start(0)  # Start with 0% duty cycle (fan off)
        print("Using hardware PWM.")

        while True:
            try:
                fan_speed = float(input("Enter fan speed (0-100, or 'q' to quit): "))

                if fan_speed == 'q':
                    break
                elif 0 <= fan_speed <= 100:
                    set_fan_speed(pwm_instance, fan_speed)
                else:
                    print("Invalid speed. Please enter a value between 0 and 100.")

            except ValueError:
                print("Invalid input. Please enter a number.")
            except KeyboardInterrupt:
                print("\nExiting program.")
                break

    except Exception as e:
        print(f"An error occurred: {e}")
        print("Falling back to software PWM.")

        # If hardware PWM fails, use software PWM
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(FAN_PIN, GPIO.OUT)
            pwm_instance = GPIO.PWM(FAN_PIN, PWM_FREQUENCY)
            pwm_instance.start(0)

            while True:
                try:
                    fan_speed = float(input("Enter fan speed (0-100, or 'q' to quit): "))

                    if fan_speed == 'q':
                        break
                    elif 0 <= fan_speed <= 100:
                        set_fan_speed(pwm_instance, fan_speed)
                    else:
                        print("Invalid speed. Please enter a value between 0 and 100.")

                except ValueError:
                    print("Invalid input. Please enter a number.")
                except KeyboardInterrupt:
                    print("\nExiting program.")
                    break

        except Exception as e2:
            print(f"Software PWM error: {e2}")
            print("Exiting.")

    finally:
        # Clean up GPIO on exit
        if 'pwm_instance' in locals():
            pwm_instance.stop()
        GPIO.cleanup()
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

