#!/usr/bin/env python3

import atexit
import signal
import time
import sys

try:
    from rainbowhat import display, lights, rainbow, buzzer
except ImportError:
    print("Rainbow HAT library not found. Running in simulation mode.")
    display = None
    lights = None
    rainbow = None
    buzzer = None

    class SimulatedDisplay:
        def print_hex(self, value):
            print(f"Simulated Display: {value:03X}")

        def clear(self):
            pass

    class SimulatedLights:
        def rgb(self, red, green, blue):
            print(f"Simulated Lights: RGB({red}, {green}, {blue})")

        def clear(self):
            pass

    class SimulatedRainbow:
        def set_pixel(self, x, y, red, green, blue):
            print(f"Simulated Rainbow: Pixel({x}, {y}) RGB({red}, {green}, {blue})")

        def show(self):
            pass

    class SimulatedBuzzer:
        def on(self):
            print("Simulated Buzzer: On")

        def off(self):
            print("Simulated Buzzer: Off")

    display = SimulatedDisplay()
    lights = SimulatedLights()
    rainbow = SimulatedRainbow()
    buzzer = SimulatedBuzzer()


# Define GPIO pins for touchpads (BCM numbering)
TOUCHPAD_A_PIN = 5
TOUCHPAD_B_PIN = 6
TOUCHPAD_C_PIN = 12

# Define bit values for each touchpad
BIT_A = 4
BIT_B = 2
BIT_C = 1

# Global variable to store the current bit states
bit_states = 0

# Function to update the display with the decimal value
def update_display(value):
    """Displays the decimal value on the 14-segment display."""
    try:
        display.print_hex(value)
    except Exception as e:
        print(f"Error updating display: {e}", file=sys.stderr)

# Function to update the discrete LEDs based on the bit states
def update_leds(bit_states):
    """Updates the discrete LEDs based on the current bit states."""
    try:
        for i in range(3):
            if (bit_states >> i) & 1:
                lights.rgb(0, 255, 0)  # Green
            else:
                lights.rgb(0, 0, 0)    # Off
    except Exception as e:
        print(f"Error updating LEDs: {e}", file=sys.stderr)

# Function to update the APA102 strip based on the bit states
def update_strip(value):
    """Updates the APA102 strip with a color based on the value."""
    try:
        if value == 0:
            for i in range(7):
                rainbow.set_pixel(i, 0, 0, 0, 0)
        elif value == 7:
            for i in range(7):
                rainbow.set_pixel(i, 0, 255, 255, 255)
        else:
            red = 255 if (bit_states >> 0) & 1 else 0
            green = 255 if (bit_states >> 1) & 1 else 0
            blue = 255 if (bit_states >> 2) & 1 else 0
            for i in range(7):
                rainbow.set_pixel(i, 0, red, green, blue)
        rainbow.show()
    except Exception as e:
        print(f"Error updating strip: {e}", file=sys.stderr)

# Function to play a tone based on the value
def play_tone(value):
    """Plays a tone based on the value."""
    try:
        if value == 0:
            buzzer.off()
        else:
            buzzer.on()
            time.sleep(0.5)
            buzzer.off()
    except Exception as e:
        print(f"Error playing tone: {e}", file=sys.stderr)

# Function to toggle the bit state for a given touchpad
def toggle_bit(touchpad_pin, bit_value):
    """Toggles the bit state for the specified touchpad."""
    global bit_states
    try:
        if rainbowhat.touch.read(touchpad_pin):
            bit_states ^= bit_value  # XOR to toggle the bit
            return True
        return False
    except Exception as e:
        print(f"Error toggling bit: {e}", file=sys.stderr)
        return False

# Function to handle touchpad events
def handle_touch(channel):
    """Handles touchpad events."""
    global bit_states

    if toggle_bit(TOUCHPAD_A_PIN, BIT_A):
        if toggle_bit(TOUCHPAD_B_PIN, BIT_B):
            toggle_bit(TOUCHPAD_C_PIN, BIT_C)

        value = bit_states
        update_display(value)
        update_leds(value)
        update_strip(value)
        play_tone(value)

        if value == 7:
            try:
                rainbowhat.light.rgb(0, 255, 0)
                rainbowhat.light.on()
            except Exception as e:
                print(f"Error turning on onboard LED: {e}", file=sys.stderr)
        else:
            try:
                rainbowhat.light.rgb(0, 0, 255)
                rainbowhat.light.off()
            except Exception as e:
                print(f"Error turning off onboard LED: {e}", file=sys.stderr)

# Function to cleanup resources on exit
def cleanup():
    """Cleans up resources before exiting."""
    print("Cleaning up...")
    try:
        display.clear()
        lights.clear()
        for i in range(7):
            rainbow.set_pixel(i, 0, 0, 0, 0)
        rainbow.show()
        buzzer.off()
        rainbowhat.light.off()
    except Exception as e:
        print(f"Error during cleanup: {e}", file=sys.stderr)

# Register the cleanup function to be called on exit
atexit.register(cleanup)

# Set up signal handlers for graceful shutdown
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    print("Received signal, exiting...")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main program loop
if __name__ == "__main__":
    print("Binary Color Demo started. Press Ctrl+C to exit.")

    # Set up touchpad interrupts
    try:
        rainbowhat.touch.press(TOUCHPAD_A_PIN, handle_touch)
        rainbowhat.touch.press(TOUCHPAD_B_PIN, handle_touch)
        rainbowhat.touch.press(TOUCHPAD_C_PIN, handle_touch)
    except Exception as e:
        print(f"Error setting up touchpad interrupts: {e}", file=sys.stderr)
        sys.exit(1)

    # Keep the program running until a signal is received
    try:
        signal.pause()
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        cleanup()

