#!/usr/bin/python3

import time
import logging
import atexit
from functools import partial

try:
    from Adafruit_PWM_Servo_Driver import PWM
except ImportError:
    print("Error: Adafruit_PWM_Servo_Driver library not found. Please install it.")
    exit(1)


# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
PWM_FREQUENCY = 60  # Hz
MIN_PULSE_WIDTH = 150  # µs
MAX_PULSE_WIDTH = 600  # µs
DEFAULT_DELAY = 0.029  # seconds
SERVO_MIN_ANGLE = -77
SERVO_MAX_ANGLE = 77

# Initialize PWM driver
try:
    pwm = PWM(0x40)  # Default address
    pwm.setPWMFreq(PWM_FREQUENCY)
    logger.info("PWM driver initialized successfully.")
except (ValueError, OSError) as e:
    logger.error(f"Failed to initialize PWM driver: {e}")
    exit(1)


def calculate_pulse(angle):
    """Calculates the PWM pulse width for a given angle."""
    zero_pulse = (MIN_PULSE_WIDTH + MAX_PULSE_WIDTH) / 2
    pulse_width = zero_pulse + (zero_pulse - MIN_PULSE_WIDTH) * angle / SERVO_MAX_ANGLE
    return int(pulse_width)


def set_servo_angle(channel, angle):
    """Sets the angle of a servo motor on a specific channel."""
    if not SERVO_MIN_ANGLE <= angle <= SERVO_MAX_ANGLE:
        logger.error(f"Invalid angle: {angle}. Angle must be between {SERVO_MIN_ANGLE} and {SERVO_MAX_ANGLE}.")
        return

    pulse = calculate_pulse(angle)
    try:
        pwm.setPWM(channel, 0, pulse)
        time.sleep(DEFAULT_DELAY)
        pwm.setPWM(channel, 0, 0)  # Stop the servo to prevent jitter
    except Exception as e:
        logger.error(f"Failed to set servo angle on channel {channel}: {e}")


def create_servo_control_function(channel):
    """Creates a partial function to control a specific servo motor."""
    return partial(set_servo_angle, channel)


