import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Define constants
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_soil_sensor(i2c_bus):
    """Initialize the soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=0x36)
    except Exception as e:
        print(f"Error initializing soil moisture sensor: {e}")
        return None

def initialize_gpio(pump_pin):
    """Initialize the GPIO pin for the water pump."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pump_pin, GPIO.OUT)
    GPIO.output(pump_pin, GPIO.LOW)  # Ensure pump is initially off

def read_moisture_level(sensor):
    """Read the moisture level from the sensor."""
    try:
        return sensor.moisture_read()
    except Exception as e:
        print(f"Error reading moisture level: {e}")
        return None

def control_water_pump(pump_pin, moisture_level, threshold):
    """Control the water pump based on the moisture level."""
    if moisture_level is not None:
        if moisture_level < threshold:
            GPIO.output(pump_pin, GPIO.HIGH)  # Activate pump
            print("Water Pump ON: Soil too dry")
        else:
            GPIO.output(pump_pin, GPIO.LOW)  # Deactivate pump
            print("Water Pump OFF: Soil moisture sufficient")

def main():
    """Main function to run the soil moisture monitoring and pump control."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    soil_sensor = initialize_soil_sensor(i2c_bus)
    if soil_sensor is None:
        return

    initialize_gpio(PUMP_GPIO_PIN)

    try:
        while True:
            moisture_level = read_moisture_level(soil_sensor)
            if moisture_level is not None:
                print(f"Soil Moisture: {moisture_level}")
                control_water_pump(PUMP_GPIO_PIN, moisture_level, MOISTURE_THRESHOLD)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)  # Ensure pump is off on exit
        GPIO.cleanup()  # Release GPIO resources
        if i2c_bus:
            i2c_bus.deinit()  # Release I2C resources
        print("GPIO and I2C resources released.")

if __name__ == "__main__":
    main()

