import logging
import RPi.GPIO as GPIO

# Configure logging for the smart garden controller
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# Define GPIO pins for the actuators
PUMP_PIN = 20
LIGHT_PIN = 21

# Intent keywords for phrase classification
INTENT_KEYWORDS = {
    "pump_on": ["turn the pump on", "start the pump"],
    "pump_off": ["turn the pump off", "stop the pump"],
    "light_toggle": ["switch the light", "toggle the light"],
}


def initialize_actuators():
    """Initialize GPIO pins for the pump and light."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT)
        GPIO.setup(LIGHT_PIN, GPIO.OUT)
        logging.info("Actuators initialized successfully.")
    except Exception as e:
        logging.error(f"Error initializing actuators: {e}")
        raise


def classify_intent(phrase):
    """Classify the intent of a phrase based on keyword matching."""
    for intent, keywords in INTENT_KEYWORDS.items():
        if any(keyword.lower() in phrase.lower() for keyword in keywords):
            return intent
    return None


def execute_intent(intent):
    """Execute the identified intent by controlling the actuators."""
    if intent == "pump_on":
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        logging.info("Pump turned ON.")
    elif intent == "pump_off":
        GPIO.output(PUMP_PIN, GPIO.LOW)
        logging.info("Pump turned OFF.")
    elif intent == "light_toggle":
        current_state = GPIO.input(LIGHT_PIN)
        GPIO.output(LIGHT_PIN, not current_state)
        logging.info("Light toggled.")
    else:
        logging.warning(f"Unknown intent: {intent}")


def main():
    """Main function to run the smart garden controller."""
    try:
        initialize_actuators()

        # Example phrases for testing
        phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]

        for phrase in phrases:
            intent = classify_intent(phrase)
            if intent:
                logging.info(f"Phrase: {phrase}, Intent: {intent}")
                execute_intent(intent)
            else:
                logging.warning(f"Could not classify phrase: {phrase}")

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure actuators are turned off and GPIO is cleaned up
        GPIO.output(PUMP_PIN, GPIO.LOW)
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        GPIO.cleanup()
        logging.info("Actuators turned OFF and GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

