#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi

This module provides a driver for the DS1338 RTC chip, utilizing the I2C interface.
It offers functionalities to read and write date and time information to the RTC.
"""

import smbus
import time
import datetime
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DS1338_I2C_ADDRESS = 0x68
DS1338_REG_SECONDS = 0x00
DS1338_REG_MINUTES = 0x01
DS1338_REG_HOURS = 0x02
DS1338_REG_DAY = 0x03
DS1338_REG_DATE = 0x04
DS1338_REG_MONTH = 0x05
DS1338_REG_YEAR = 0x06
DS1338_REG_CONTROL = 0x07

# Global variable for I2C bus
bus = None

def bcd_to_int(bcd):
    """Converts Binary Coded Decimal (BCD) to integer."""
    try:
        return int(bcd / 16) * 10 + int(bcd % 16)
    except TypeError:
        logger.error("Invalid BCD value: %s", bcd)
        return None

def int_to_bcd(integer):
    """Converts integer to Binary Coded Decimal (BCD)."""
    if not 0 <= integer <= 99:
        raise ValueError("Integer must be between 0 and 99 for BCD conversion.")
    return int(integer / 10) * 16 + int(integer % 10)

def read_register(register_address):
    """Reads a byte from the specified register."""
    global bus
    try:
        return bus.read_byte_data(DS1338_I2C_ADDRESS, register_address)
    except IOError as e:
        logger.error("I2C read error: %s", e)
        return None

def write_register(register_address, value):
    """Writes a byte to the specified register."""
    global bus
    try:
        bus.write_byte_data(DS1338_I2C_ADDRESS, register_address, value)
    except IOError as e:
        logger.error("I2C write error: %s", e)
        return False
    return True

def read_time_register(register_address):
    """Reads and converts a time register value to BCD."""
    value = read_register(register_address)
    if value is None:
        return None
    return bcd_to_int(value)

def write_time_register(register_address, value):
    """Converts a BCD value and writes it to a time register."""
    if value is None:
        return False
    bcd_value = int_to_bcd(value)
    return write_register(register_address, bcd_value)

def read_all():
    """Reads all time registers and returns a tuple of integers."""
    year = read_time_register(DS1338_REG_YEAR)
    month = read_time_register(DS1338_REG_MONTH)
    date = read_time_register(DS1338_REG_DATE)
    day = read_time_register(DS1338_REG_DAY)
    hours = read_time_register(DS1338_REG_HOURS) & 0x3F  # Mask 24/12 bit and reserved bits
    minutes = read_time_register(DS1338_REG_MINUTES)
    seconds = read_time_register(DS1338_REG_SECONDS)
    return year, month, date, day, hours, minutes, seconds

def write_all(year=None, month=None, date=None, day=None, hours=None, minutes=None, seconds=None):
    """Writes all time registers."""
    if year is not None:
        write_time_register(DS1338_REG_YEAR, year)
    if month is not None:
        write_time_register(DS1338_REG_MONTH, month)
    if date is not None:
        write_time_register(DS1338_REG_DATE, date)
    if day is not None:
        write_time_register(DS1338_REG_DAY, day)
    if hours is not None:
        write_time_register(DS1338_REG_HOURS, hours)
    if minutes is not None:
        write_time_register(DS1338_REG_MINUTES, minutes)
    if seconds is not None:
        write_time_register(DS1338_REG_SECONDS, seconds)

def read_datetime(century=21):
    """Reads the date and time and returns a datetime object."""
    year, month, date, _, hours, minutes, seconds = read_all()
    if any(v is None for v in [year, month, date, hours, minutes, seconds]):
        return None
    try:
        return datetime.datetime(century * 100 + year, month, date, hours, minutes, seconds)
    except ValueError as e:
        logger.error("Invalid date/time data: %s", e)
        return None

def write_datetime(dt):
    """Writes the date and time from a datetime object."""
    write_all(
        year=dt.year % 100,
        month=dt.month,
        date=dt.day,
        day=dt.isoweekday(),
        hours=dt.hour,
        minutes=dt.minute,
        seconds=dt.second,
    )

def initialize():
    """Initializes the DS1338."""
    global bus
    try:
        bus = smbus.SMBus(1)  # Use I2C bus 1
        # Check if the device is present by reading the seconds register
        if read_register(DS1338_REG_SECONDS) is None:
            raise IOError("DS1338 not found on I2C bus")
        logger.info("DS1338 initialized successfully.")
        return True
    except IOError as e:
        logger.error("DS1338 initialization failed: %s", e)
        return False

def cleanup():
    """Releases the I2C bus."""
    global bus
    if bus:
        try:
            bus.close()
            logger.info("I2C bus released.")
        except Exception as e:
            logger.error("Error closing I2C bus: %s", e)

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
