    """Reads the date and time and returns a datetime object."""
    year, month, date, _, hours, minutes, seconds = read_all()
    if any(v is None for v in [year, month, date, hours, minutes, seconds]):
        return None
    try:
        return datetime.datetime(century * 100 + year, month, date, hours, minutes, seconds)
