#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi

This module provides a driver for the DS1338 RTC chip, utilizing the I2C interface.
It offers functionalities to read and write date and time information to the RTC.
"""

import smbus
import time
from datetime import datetime, timezone
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DS1338_I2C_ADDRESS = 0x68
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07

# --- Functional Approach ---

def bcd_to_int(bcd_value):
    """Decode a 2x4bit BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logger.error(f"Invalid BCD value: {bcd_value}")
        return None

def int_to_bcd(integer_value):
    """Encode an integer to 2x4bit BCD."""
    if not 0 <= integer_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (integer_value // 10 << 4) | (integer_value % 10)

def read_register(bus, register_address):
    """Read a byte from the specified register."""
    try:
        return bus.read_byte_data(DS1338_I2C_ADDRESS, register_address)
    except IOError as e:
        logger.error(f"I/O error reading register 0x{register_address:02X}: {e}")
        raise

def write_register(bus, register_address, value):
    """Write a byte to the specified register."""
    try:
        bus.write_byte_data(DS1338_I2C_ADDRESS, register_address, value)
    except IOError as e:
        logger.error(f"I/O error writing to register 0x{register_address:02X}: {e}")
        raise

def read_time_register(bus, register_address):
    """Read and decode a time register (BCD)."""
    return bcd_to_int(read_register(bus, register_address))

def read_all(bus):
    """Read all time registers and return as a tuple."""
    try:
        seconds = read_time_register(bus, REG_SECONDS)
        minutes = read_time_register(bus, REG_MINUTES)
        hours = read_time_register(bus, REG_HOURS) & 0x3F  # 24-hour mode
        day = read_time_register(bus, REG_DAY)
        date = read_time_register(bus, REG_DATE)
        month = read_time_register(bus, REG_MONTH)
        year = read_time_register(bus, REG_YEAR) + 2000
        return year, month, date, day, hours, minutes, seconds
    except Exception as e:
        logger.error(f"Error reading all time registers: {e}")
        raise

def read_datetime(bus):
    """Read the current time and return as a datetime object."""
    year, month, date, _, hours, minutes, seconds = read_all(bus)
    try:
        return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)
    except ValueError as e:
        logger.error(f"Invalid date/time values: {e}")
        raise

def write_time_register(bus, register_address, value):
    """Write a time value (integer) to a register (BCD)."""
    write_register(bus, register_address, int_to_bcd(value))

def write_all(bus, year, month, date, day, hours, minutes, seconds):
    """Write all time registers."""
    try:
        write_time_register(bus, REG_SECONDS, seconds)
        write_time_register(bus, REG_MINUTES, minutes)
        write_time_register(bus, REG_HOURS, hours | 0x40)  # Set 24-hour mode
        write_time_register(bus, REG_DAY, day)
        write_time_register(bus, REG_DATE, date)
        write_time_register(bus, REG_MONTH, month)
        write_time_register(bus, REG_YEAR, year - 2000)
    except ValueError as e:
        logger.error(f"Invalid time values: {e}")
        raise
    except Exception as e:
        logger.error(f"Error writing all time registers: {e}")
        raise

def write_datetime(bus, dt):
    """Write the current time from a datetime object."""
    write_all(bus, dt.year, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)

def write_now(bus):
    """Write the current system time to the RTC."""
    write_datetime(bus, datetime.now(timezone.utc))

# --- Class Implementation ---

class DS1338:
    """Driver class for the DS1338 RTC chip."""

    def __init__(self, i2c_bus_number=1):
        """Initialize the DS1338 driver."""
        try:
            self.bus = smbus.SMBus(i2c_bus_number)
        except FileNotFoundError:
            logger.error(f"I2C bus {i2c_bus_number} not found. Check your Raspberry Pi configuration.")
            raise
        except Exception as e:
            logger.error(f"Failed to initialize I2C bus: {e}")
            raise

    def __enter__(self):
        """Context manager entry point."""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point, closes the I2C bus."""
        self.close()

    def close(self):
        """Close the I2C bus connection."""
        try:
            self.bus.close()
            logger.info("I2C bus closed successfully.")
        except Exception as e:
            logger.error(f"Error closing I2C bus: {e}")

    def read_all(self):
        """Read all time registers and return as a tuple."""
        return read_all(self.bus)

    def read_datetime(self):
        """Read the current time and return as a datetime object."""
        return read_datetime(self.bus)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all time registers."""
        write_all(self.bus, year, month, date, day, hours, minutes, seconds)

    def write_datetime(self, dt):
        """Write the current time from a datetime object."""
        write_datetime(self.bus, dt)

    def write_now(self):
        """Write the current system time to the RTC."""
        write_now(self.bus)

# --- Main Execution ---

if __name__ == '__main__':
    try:
        with DS1338() as rtc:
            current_time = rtc.read_datetime()
            print(f"Current time: {current_time.isoformat()}")
    except IOError as e:
        logger.error(f"DS1338 not found or I/O error: {e}")
        print(f"Error: DS1338 not found or I/O error. Check your wiring and I2C configuration. {e}", file=sys.stderr)
        exit(1)
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
        exit(1)

