#!/usr/bin/env python3

# radiation_monitor.py
# Monitors radiation levels from a UART-connected sensor and triggers an alarm.
# Target: Raspberry Pi 3 Model B+

import serial
import time
import RPi.GPIO as GPIO

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0
SLEEP_INTERVAL = 1

def initialize_serial(port, baud, timeout):
    """Initializes the serial port."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for the alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)  # Ensure alarm is initially off

def read_radiation_level(serial_port):
    """Reads a radiation level from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor.")
        return None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None

def control_alarm(pin, radiation_level, threshold):
    """Controls the alarm based on the radiation level."""
    if radiation_level is not None:
        if radiation_level > threshold:
            GPIO.output(pin, GPIO.HIGH)
            return True
        else:
            GPIO.output(pin, GPIO.LOW)
            return False
    return False  # Return current state if radiation_level is None

def main():
    """Main function to monitor radiation levels."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        exit(1)

    initialize_gpio(ALARM_GPIO_PIN)
    alarm_active = False

    try:
        while True:
            radiation = read_radiation_level(serial_connection)

            if radiation is not None:
                print(f"Radiation Level: {radiation:.2f} µSv/h")

                new_alarm_active = control_alarm(ALARM_GPIO_PIN, radiation, RADIATION_THRESHOLD)
                if new_alarm_active != alarm_active:
                    alarm_active = new_alarm_active
                    if alarm_active:
                        print("Alarm: Radiation level exceeded threshold!")
                    else:
                        print("Alarm: Radiation level back to normal.")

            time.sleep(SLEEP_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

