# Monitors water flow using a UART-based sensor on a Raspberry Pi.

import serial
import time
import RPi.GPIO as GPIO

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# GPIO pin for the flow alarm
FLOW_ALARM_PIN = 17

# Flow rate threshold (L/min)
FLOW_THRESHOLD = 10.0

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for the flow alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)

def read_flow_rate(serial_connection):
    """Reads the flow rate from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor.")
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None

def control_flow_alarm(pin, flow_rate, threshold):
    """Controls the flow alarm based on the flow rate."""
    if flow_rate is not None:
        if flow_rate > threshold:
            GPIO.output(pin, GPIO.HIGH)  # Activate alarm
        else:
            GPIO.output(pin, GPIO.LOW)   # Deactivate alarm

def main():
    """Main function to monitor water flow."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        return

    initialize_gpio(FLOW_ALARM_PIN)

    try:
        while True:
            flow_rate = read_flow_rate(serial_connection)
            if flow_rate is not None:
                print(f'Flow Rate: {flow_rate:.2f} L/min')
                control_flow_alarm(FLOW_ALARM_PIN, flow_rate, FLOW_THRESHOLD)
            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up.")

if __name__ == "__main__":
    main()

