import serial
import time
import pynmea2

# Define serial port and baud rate
SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_gps_data(serial_port):
    """Reads a line of data from the serial port and returns it."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        return data
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def parse_gprmc_data(data):
    """Parses the GPRMC sentence and extracts latitude and longitude."""
    try:
        if data.startswith('$GPRMC'):
            msg = pynmea2.parse(data)
            latitude = msg.latitude
            longitude = msg.longitude
            return latitude, longitude
        else:
            return None, None
    except pynmea2.ParseError as e:
        print(f"Error parsing NMEA sentence: {e}")
        return None, None

def convert_to_decimal_degrees(raw_latitude, raw_longitude):
    """Converts raw GPS coordinates (ddmm.mmmm) to decimal degrees."""
    try:
        latitude = convert_coordinate(raw_latitude)
        longitude = convert_coordinate(raw_longitude)
        return latitude, longitude
    except (ValueError, TypeError) as e:
        print(f"Error converting coordinates: {e}")
        return None, None

def convert_coordinate(raw_coordinate):
    """Converts a single coordinate (latitude or longitude) from ddmm.mmmm to dd.dddddd."""
    try:
        degrees_minutes = raw_coordinate
        degrees = degrees_minutes // 100
        minutes = degrees_minutes - (degrees * 100)
        decimal_degrees = degrees + (minutes / 60)
        return decimal_degrees
    except (ValueError, TypeError) as e:
        print(f"Error converting coordinate: {e}")
        return None

def main():
    """Main function to read GPS data and print coordinates."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            gps_data = read_gps_data(serial_connection)

            if gps_data:
                latitude, longitude = parse_gprmc_data(gps_data)

                if latitude is not None and longitude is not None:
                    print(f"Latitude: {latitude}, Longitude: {longitude}")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

