import json
import time
import logging
from threading import Thread, Lock
from typing import List, Dict, Any

import serial
from flask import Flask, Response, request, jsonify, abort

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
DEFAULT_TIMEOUT = 1
WEB_SERVICE_HOST = '0.0.0.0'
WEB_SERVICE_PORT = 5000
DATA_STORE_LOCK = Lock()

# Global data store (in-memory database)
DATA_STORE: List[Dict[str, Any]] = []
DATA_STORE_NEXT_ID = 2  # Start at 2 to avoid clashing with the initial seed


class SerialPortManager:
    """Context manager for serial port resource management."""

    def __init__(self, port: str, baudrate: int, timeout: int):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port = None

    def __enter__(self):
        """Opens the serial port."""
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Serial port {self.port} opened successfully.")
            return self.serial_port
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            raise

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Closes the serial port."""
        if self.serial_port and self.serial_port.is_open:
            self.serial_port.close()
            logging.info(f"Serial port {self.port} closed.")


def initialize_data_store() -> None:
    """Initializes the data store with sample data."""
    global DATA_STORE, DATA_STORE_NEXT_ID
    with DATA_STORE_LOCK:
        DATA_STORE = [
            {'id': 1, 'name': 'Item 1', 'done': False},
            {'id': 2, 'name': 'Item 2', 'done': False}
        ]
        DATA_STORE_NEXT_ID = DATA_STORE[-1]['id'] + 1


def get_instrument_version(serial_port) -> str:
    """Queries the instrument for its version information."""
    try:
        with SerialPortManager(serial_port, DEFAULT_BAUDRATE, DEFAULT_TIMEOUT) as port:
            port.write(b"*IDN?\n")
            response = port.readline().decode('ascii', errors='replace').strip()
            return response
    except Exception as e:
        logging.error(f"Error getting instrument version: {e}")
        return "N/A"


def get_data() -> List[Dict[str, Any]]:
    """Retrieves all data from the data store."""
    with DATA_STORE_LOCK:
        return DATA_STORE[:]  # Return a copy to avoid modification


def get_data_item(item_id: int) -> Dict[str, Any]:
    """Retrieves a specific data item from the data store."""
    with DATA_STORE_LOCK:
        item = next((item for item in DATA_STORE if item['id'] == item_id), None)
        if item:
            return item
        else:
            abort(404, description=f"Data item with ID {item_id} not found")


def create_data_item(name: str, done: bool) -> Dict[str, Any]:
    """Creates a new data item and adds it to the data store."""
    global DATA_STORE_NEXT_ID
    with DATA_STORE_LOCK:
        new_item = {
            'id': DATA_STORE_NEXT_ID,
            'name': name,
            'done': done
        }
        DATA_STORE.append(new_item)
        DATA_STORE_NEXT_ID += 1
        return new_item


def update_data_item(item_id: int, name: str, done: bool) -> Dict[str, Any]:
    """Updates an existing data item in the data store."""
    with DATA_STORE_LOCK:
        item = next((item for item in DATA_STORE if item['id'] == item_id), None)
        if item:
            item['name'] = name
            item['done'] = done
            return item
        else:
            abort(404, description=f"Data item with ID {item_id} not found")


def delete_data_item(item_id: int) -> None:
    """Deletes a data item from the data store."""
    with DATA_STORE_LOCK:
        item = next((item for item in DATA_STORE if item['id'] == item_id), None)
        if item:
            DATA_STORE.remove(item)
        else:
            abort(404, description=f"Data item with ID {item_id} not found")


def validate_data_item(name: str, done: bool) -> None:
    """Validates the name and done fields of a data item."""
    if not isinstance(name, str) or not name.strip():
        raise ValueError("Name must be a non-empty string.")
    if not isinstance(done, bool):
        raise ValueError("Done must be a boolean.")


def api_get_version() -> Response:
    """API endpoint to retrieve instrument version information."""
    try:
        version = get_instrument_version(DEFAULT_SERIAL_PORT)
        return Response(version, mimetype='text/plain')
    except Exception as e:
        logging.error(f"Error getting instrument version: {e}")
        return Response("Error getting instrument version", status=500, mimetype='text/plain')


def api_get_data() -> Response:
    """API endpoint to retrieve all data."""
    try:
        data = get_data()
        return jsonify(data)
    except Exception as e:
        logging.error(f"Error getting data: {e}")
        return Response(str(e), status=500, mimetype='text/plain')


def api_get_data_item(item_id: int) -> Response:
    """API endpoint to retrieve a specific data item."""
    try:
        data_item = get_data_item(item_id)
        return jsonify(data_item)
    except Exception as e:
        logging.error(f"Error getting data item: {e}")
        return Response(str(e), status=500, mimetype='text/plain')


def api_create_data_item() -> Response:
    """API endpoint to create a new data item."""
    try:
        name = request.json.get('name')
        done = request.json.get('done', False)

        validate_data_item(name, done)

        new_item = create_data_item(name, done)
        return jsonify(new_item), 201

    except (KeyError, ValueError) as e:
        logging.error(f"Invalid input data: {e}")
        return Response(str(e), status=400, mimetype='text/plain')
    except Exception as e:
        logging.error(f"Error creating data item: {e}")
        return Response(str(e), status=500, mimetype='text/plain')


def api_update_data_item(item_id: int) -> Response:
    """API endpoint to update a specific data item."""
    try:
        name = request.json.get('name')
        done = request.json.get('done', False)

        validate_data_item(name, done)

        updated_item = update_data_item(item_id, name, done)
        return jsonify(updated_item)

    except (KeyError, ValueError) as e:
        logging.error(f"Invalid input data: {e}")
        return Response(str(e), status=400, mimetype='text/plain')
    except Exception as e:
        logging.error(f"Error updating data item: {e}")
        return Response(str(e), status=500, mimetype='text/plain')


def api_delete_data_item(item_id: int) -> Response:
    """API endpoint to delete a specific data item."""
    try:
        delete_data_item(item_id)
        return Response(status=204)
    except Exception as e:
        logging.error(f"Error deleting data item: {e}")
        return Response(str(e), status=500, mimetype='text/plain')


def create_api_app() -> Flask:
    """Creates and configures the Flask API application."""
    app = Flask(__name__)

    @app.route('/version', methods=['GET'])
    def version() -> Response:
        return api_get_version()

    @app.route('/data', methods=['GET'])
    def data() -> Response:
        return api_get_data()

    @app.route('/data/<int:item_id>', methods=['GET'])
    def data_item(item_id: int) -> Response:
        return api_get_data_item(item_id)

    @app.route('/data', methods=['POST'])
    def create_item() -> Response:
        return api_create_data_item()

    @app.route('/data/<int:item_id>', methods=['PUT'])
    def update_item(item_id: int) -> Response:
        return api_update_data_item(item_id)

    @app.route('/data/<int:item_id>', methods=['DELETE'])
    def delete_item(item_id: int) -> Response:
        return api_delete_data_item(item_id)

    return app


def run_web_service(app: Flask) -> None:
    """Runs the Flask web service in a separate thread."""
    try:
        app.run(host=WEB_SERVICE_HOST, port=WEB_SERVICE_PORT, debug=False, use_reloader=False)
    except Exception as e:
        logging.error(f"Error running web service: {e}")


def main() -> None:
    """Main function to initialize and start the application."""
    logging.info("Starting Raspberry Pi Web API Service...")

    initialize_data_store()

    api_app = create_api_app()

    # Start the web service in a separate thread
    web_service_thread = Thread(target=run_web_service, args=(api_app,))
    web_service_thread.daemon = True  # Allow the main thread to exit even if this thread is running
    web_service_thread.start()

    logging.info("Web API Service started. Press Ctrl+C to exit.")

    try:
        while True:
            time.sleep(1)  # Keep the main thread alive
    except KeyboardInterrupt:
        logging.info("Shutting down Web API Service...")
    finally:
        # Perform any necessary cleanup here, such as closing serial ports
        logging.info("Web API Service stopped.")


if __name__ == "__main__":
    main()

