def api_update_data_item(item_id: int) -> Response:
    """API endpoint to update a specific data item."""
    try:
        name = request.json.get('name')
        done = request.json.get('done', False)

        validate_data_item(name, done)

        updated_item = update_data_item(item_id, name, done)
        return jsonify(updated_item)

    except (KeyError, ValueError) as e:
        logging.error(f"Invalid input data: {e}")
        return Response(str(e), status=400, mimetype='text/plain')
    except Exception as e:
        logging.error(f"Error updating data item: {e}")
        return Response(str(e), status=500, mimetype='text/plain')


def api_delete_data_item(item_id: int) -> Response:
    """API endpoint to delete a specific data item."""
    try:
        delete_data_item(item_id)
        return Response(status=204)
    except Exception as e:
        logging.error(f"Error deleting data item: {e}")
        return Response(str(e), status=500, mimetype='text/plain')


def create_api_app() -> Flask:
    """Creates and configures the Flask API application."""
    app = Flask(__name__)

    @app.route('/version', methods=['GET'])
    def version() -> Response:
        return api_get_version()

    @app.route('/data', methods=['GET'])
    def data() -> Response:
        return api_get_data()

    @app.route('/data/<int:item_id>', methods=['GET'])
    def data_item(item_id: int) -> Response:
        return api_get_data_item(item_id)

    @app.route('/data', methods=['POST'])
    def create_item() -> Response:
        return api_create_data_item()

    @app.route('/data/<int:item_id>', methods=['PUT'])
    def update_item(item_id: int) -> Response:
        return api_update_data_item(item_id)

    @app.route('/data/<int:item_id>', methods=['DELETE'])
    def delete_item(item_id: int) -> Response:
        return api_delete_data_item(item_id)

    return app


def run_web_service(app: Flask) -> None:
    """Runs the Flask web service in a separate thread."""
    try:
        app.run(host=WEB_SERVICE_HOST, port=WEB_SERVICE_PORT, debug=False, use_reloader=False)
    except Exception as e:
        logging.error(f"Error running web service: {e}")


def main() -> None:
    """Main function to initialize and start the application."""
    logging.info("Starting Raspberry Pi Web API Service...")

    initialize_data_store()

    api_app = create_api_app()

    # Start the web service in a separate thread
    web_service_thread = Thread(target=run_web_service, args=(api_app,))
    web_service_thread.daemon = True  # Allow the main thread to exit even if this thread is running
    web_service_thread.start()

    logging.info("Web API Service started. Press Ctrl+C to exit.")

    try:
        while True:
            time.sleep(1)  # Keep the main thread alive
    except KeyboardInterrupt:
        logging.info("Shutting down Web API Service...")
    finally:
