from flask import Flask, Response, request, jsonify, abort
import json
import time
import serial

# Initialize Flask application
app = Flask(__name__)

# Serial port configuration for the SCPI instrument
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Data store for simulated sensor readings
sensor_data = [{"id": 1, "sensor": "Temperature", "value": 25.0, "unit": "C"},
              {"id": 2, "sensor": "Humidity", "value": 60.0, "unit": "%"}]

# Initialize serial connection
try:
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    serial_connection = None  # Handle the case where serial port fails to open

# Function to query the SCPI instrument for identification
def query_instrument(command):
    """Sends an SCPI command to the instrument and returns the response."""
    if serial_connection is None:
        return "Serial port not initialized"
    try:
        serial_connection.write(f'{command}\n'.encode())
        time.sleep(0.1)  # Allow time for the instrument to respond
        response = serial_connection.read(1000).decode().strip()
        return response
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return f"Serial communication error: {e}"
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return f"An unexpected error occurred: {e}"

# Route to retrieve instrument identification
@app.route('/version', methods=['GET'])
def get_instrument_version():
    """Retrieves the instrument identification information."""
    response = query_instrument('*IDN?')
    return Response(response.replace('\n', '<br><br>'), mimetype='text/html')

# Route to retrieve all sensor readings
@app.route('/getdata', methods=['GET'])
def get_all_data():
    """Returns all sensor readings as a JSON list."""
    return jsonify(sensor_data)

# Route to retrieve a specific sensor reading
@app.route('/getset/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    """Returns a specific sensor reading based on the ID."""
    item = next((item for item in sensor_data if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        abort(404)

# Route to add a new sensor reading (POST with JSON)
@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def add_data_item(item_id, name):
    """Adds a new sensor reading to the list."""
    new_item = {
        "id": item_id,  # Use the provided ID, but ensure it's unique
        "sensor": name,
        "value": 10.0,
        "unit": "N/A"
    }
    sensor_data.append(new_item)
    return jsonify(sensor_data)

# Route to handle POST requests with JSON data
@app.route('/postjson', methods=['POST'])
def handle_post_json():
    """Handles POST requests with JSON data."""
    if request.headers['Content-Type'] == 'application/json':
        try:
            data = request.get_json()
            new_item = {
                "id": data.get('id', len(sensor_data) + 1),  # Auto-increment ID if not provided
                "sensor": data.get('sensor', 'Unknown'),
                "value": data.get('value', 0.0),
                "unit": data.get('unit', 'N/A')
            }
            sensor_data.append(new_item)
            return jsonify(sensor_data), 201  # 201 Created
        except (json.JSONDecodeError, TypeError) as e:
            print(f"Error decoding JSON: {e}")
            return jsonify({"error": "Invalid JSON data"}), 400  # 400 Bad Request
    else:
        return jsonify({"error": "Invalid Content-Type. Expecting application/json"}), 400

# Route to handle POST requests with form data
@app.route('/postjson', methods=['POST'])
def handle_post_form():
    """Handles POST requests with form data."""
    if request.headers['Content-Type'] == 'application/x-www-form-urlencoded':
        try:
            data = request.form.to_dict()
            new_item = {
                "id": int(data.get('id', len(sensor_data) + 1)),  # Auto-increment ID if not provided
                "sensor": data.get('sensor', 'Unknown'),
                "value": float(data.get('value', 0.0)),
                "unit": data.get('unit', 'N/A')
            }
            sensor_data.append(new_item)
            return jsonify(sensor_data), 201  # 201 Created
        except (ValueError, TypeError) as e:
            print(f"Error converting form data: {e}")
            return jsonify({"error": "Invalid form data"}), 400  # 400 Bad Request
    else:
        return jsonify({"error": "Invalid Content-Type. Expecting application/x-www-form-urlencoded"}), 400

# Route to retrieve the current list of sensor readings
@app.route('/postjson', methods=['GET'])
def get_current_data():
    """Returns the current list of sensor readings."""
    return jsonify(sensor_data)

# Error handler for 404 Not Found
@app.errorhandler(404)
def not_found(error):
    """Handles 404 Not Found errors."""
    return jsonify({"error": "Not found"}), 404

# Error handler for 500 Internal Server Error
@app.errorhandler(500)
def internal_server_error(error):
    """Handles 500 Internal Server Error errors."""
    return jsonify({"error": "Internal server error"}), 500

# Main execution block
if __name__ == '__main__':
    try:
        # Start the Flask development server
        app.run(debug=True, host='0.0.0.0')
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Ensure the serial port is closed on exit
        if serial_connection:
            serial_connection.close()
            print("Serial port closed.")

